import json,runpy,sys
from pathlib import Path
worker,config=sys.argv[1:]; expected=json.loads(Path(config).read_text()); accesses=[]
class Boundary(BaseException):pass
def audit(event,args):
 if event in ('os.mkdir','open') and str(args[0]).startswith('/mnt/'):
  accesses.append((event,str(args[0])));raise AssertionError('CPU control attempted a cloud-path operation')
sys.addaudithook(audit)
def trace(frame,event,arg):
 if event=='call' and frame.f_code.co_filename==worker and frame.f_code.co_name=='_python_path_with_wheels':
  assert frame.f_locals['env']['PYTHONPATH']==expected['source_snapshot']
  assert str(frame.f_locals['wheelhouse'])==expected['wheelhouse']
  assert not any(n.startswith(('torch','vllm','steptron')) for n in sys.modules)
  print(json.dumps({'status':'PASS_WORKER_ENTRY_BEFORE_RUNTIME_AND_CLOUD','dependency_preloads':0,'GPU_platform_cloud_calls':0}));raise Boundary
 return trace
sys.argv=[worker,'--config',config];sys.settrace(trace)
try:runpy.run_path(worker,run_name='__main__')
except Boundary:pass
else:raise AssertionError('Missing worker boundary')
assert not accesses

import json,runpy,sys,types,os
from pathlib import Path
launcher,config,root=sys.argv[1:]; expected=json.loads(Path(config).read_text())
class Boundary(BaseException):pass
class ResourceConfig:
 preemptible=False
 def __init__(self,**kwargs):self.__dict__.update(kwargs)
def spawn(resource,**kwargs):
 assert (resource.cpu,resource.gpu,resource.mem_gb,resource.preemptible)==(16,1,128,False)
 assert resource.image==expected['image'] and resource.mounts==[expected['cloud_mount']]
 assert kwargs['charged_group']=='codesign' and kwargs['code_mount_point']==root
 assert expected['worker'] in kwargs['command'] and 'timeout 1800 python3' in kwargs['command']
 print(json.dumps({'status':'PASS_LAUNCHER_RESOURCE_CPU_STANDIN_NOT_SDK_GATE','cpu':resource.cpu,'gpu':resource.gpu,'mem_gb':resource.mem_gb,'preemptible':resource.preemptible,'platform_calls':0,'launcher_default_omits_explicit_preemptible':True}));raise Boundary
def trace(frame,event,arg):
 if event=='call' and frame.f_code.co_filename==launcher and frame.f_code.co_name=='submit':
  assert not any(n.startswith(('torch','vllm','steptron')) for n in sys.modules)
  for name,attrs in {'steptron.exp.base_exp':{'ResourceConfig':ResourceConfig},'steptron.utils.stepmind':{'spawn_tasks':spawn}}.items():
   module=types.ModuleType(name);module.__dict__.update(attrs);sys.modules[name]=module
 return trace
os.environ['STEPMIND_BACKEND']='rjob';sys.argv=[launcher,'submit','--config',config];sys.settrace(trace)
try:runpy.run_path(launcher,run_name='__main__')
except Boundary:pass
else:raise AssertionError('Missing resource boundary')

